from typing import Dict, Any

def get_30min_angst_romance_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Khi Hoa Sơn Tra Tàn Lụi: 5 Năm Oan Khuất Nhận Tội Thay Người Yêu Và Trái Tim Vụn Vỡ"
    part1_full = "Cánh cổng sắt trại giam ngoại ô mở ra vào một buổi sáng sương mù lạnh buốt sau năm năm tôi ngồi tù nhận tội thay Phó Cẩm Thần, nhưng thứ đón tôi ở đầu đường lại là tấm thiệp cưới mạ vàng của anh ta. Cả sảnh tiệc đính hôn xa hoa với hàng trăm quan khách thượng lưu bỗng chốc rơi vào im lặng như tờ. Những tiếng cười nói rôm rả, tiếng chạm ly pha lê vang lừng bỗng chốc ngưng bặt hoàn toàn. Những vị khách quyền quý trong những bộ váy dạ hội lấp lánh kim cương trố mắt nhìn người con gái vừa xuất hiện ở trung tâm sảnh tiệc.\n\nĐứng giữa thảm đỏ lộng lẫy, người con gái mặc chiếc áo khoác dạ màu nâu xỉn đã cũ sờn rách mép, mái tóc đen dài gầy guộc ướt sũng nước mưa – Thẩm Diên – vừa bước chân ra khỏi cánh cổng sắt lạnh ngắt của trại giam số 4 sau đúng một nghìn tám trăm hai mươi lăm ngày bị giam cầm trong bóng tối tủi nhục. Đôi bàn tay cô từng là bàn tay của một nghệ sĩ dương cầm thiên tài với những giải thưởng quốc tế danh giá, từng lướt trên những phím đàn dương cầm mượt mà làm say đắm biết bao thính phòng hòa nhạc châu Âu. Thế nhưng giờ đây, các đốt ngón tay thon thả năm nào đã bị biến dạng vẹo vọ vì những tháng ngày lao động khổ sai trong hầm mỏ khai thác đá của nhà tù, và trên mu bàn tay chằng chịt những vết sẹo bỏng sâu hoắm do bị những kẻ thù địch trong tù hành hạ bạo lực năm xưa.\n\nTrước mặt cô, vị tổng tài quyền lực nhất giới thương trường – Phó Cẩm Thần – trong bộ âu phục đặt may riêng lộng lẫy, đứng bên cạnh thiên kim tiểu thư Bạch Uyển Đình đang khoác tay anh tình tứ. Khuôn mặt Phó Cẩm Thần thoáng qua một nét chấn động cực độ, đồng tử anh co thắt lại trong giây lát khi nhìn thấy bóng hình thân quen từng khắc sâu trong ký ức. Nhưng rồi rất nhanh, sự chấn động ấy lập tức bị sự lạnh lùng tàn nhẫn quen thuộc che lấp. Anh khẽ nheo đôi mắt phượng nguy hiểm, siết chặt ly rượu trên tay, giọng nói trầm thấp vang lên đầy khinh bạc và ghê tởm: 'Thẩm Diên! Ai cho phép một kẻ mang tiền án tiền sự như cô đặt chân đến đây phá đám? Năm năm trước cô lái xe trong lúc say xỉn gây tai nạn chết người trên đường cao tốc, tôi đã nể tình nghĩa xưa cũ mà thuê luật sư hàng đầu giảm án cho cô từ mười năm xuống còn năm năm tù giam, cô còn chưa biết đủ hay sao? Đừng tưởng diễn màn kịch đáng thương nghèo khổ này thì tôi sẽ mềm lòng cho cô một đồng tiền bồi thường nào! Bảo vệ, lập tức tống cổ người đàn bà điên này ra ngoài! Đừng để cô ta làm bẩn buổi tiệc của tôi và Uyển Đình!'.\n\nTừng lời nói cay độc, vô tình của người đàn ông mà Thẩm Diên từng dùng cả tính mạng, danh dự và thanh xuân để yêu thương như những mũi dao nhọn hoắt đâm nát cõi lòng cô! Năm năm trước, trong đêm mưa bão sấm sét định mệnh trên đường vành đai ven sông, chính chiếc siêu xe thể thao do Phó Cẩm Thần cầm lái đã mất lái đâm vào dải phân cách và va chạm kinh hoàng với một chiếc xe máy đi cùng chiều. Khi chiếc xe dừng lại bên bờ vực, Phó Cẩm Thần đã bất tỉnh nhân sự trên vô lăng vì nồng độ cồn trong máu quá cao sau bữa tiệc chiêu đãi đối tác, và trên ghế phụ là tập tài liệu sáp nhập dự án nghìn tỷ của tập đoàn Phó Thị. Nếu Phó Cẩm Thần bị cảnh sát giao thông xét nghiệm và kết tội lái xe say xỉn gây tai nạn chết người, anh không chỉ đối mặt với án tù cả chục năm mà toàn bộ cơ nghiệp dòng họ Phó Thị sẽ rơi vào cảnh phá sản, cổ phiếu bị xé nát trên sàn chứng khoán.\n\nVì yêu anh đến mức mù quáng, cô gái hai mươi tuổi tràn đầy tương lai Thẩm Diên đã không ngần ngại tự mình trèo sang ghế lái, nắm lấy chiếc vô lăng vấy máu, dọn sạch mọi dấu vết của anh rồi bước xuống nhận hết mọi tội lỗi về mình trước còi xe cảnh sát! Trước vành móng ngựa của phiên tòa sơ thẩm, cô đã cắn chặt môi chấp nhận mọi lời kết tội, chịu đựng sự phỉ báng nhục nhã của dư luận xã hội, sự thóa mạ của báo chí truyền thông, và nỗi đau đớn khi bị chính gia đình ruột thịt từ mặt đuổi ra khỏi dòng họ... tất cả chỉ để giữ cho người đàn ông cô yêu một tiền đồ trong sạch, một vị thế tổng tài lẫy lừng không một vết nhơ!\n\nThế nhưng tấn bi kịch ghê rợn nhất mà Thẩm Diên phải đón nhận lại xảy ra vào ngày cô bước qua cánh cổng sắt trại giam. Người duy nhất đến thăm cô không phải là Phó Cẩm Thần – người mà cô hy sinh cả đời để cứu vớt – mà lại chính là Bạch Uyển Đình trong bộ váy dạ hội lộng lẫy cùng nụ cười độc địa như mãng xà: 'Cảm ơn cô Thẩm đã ngu ngốc thế mạng vào tù thay cho Cẩm Thần nhé! Nhưng cô có biết nạn nhân trên chiếc xe máy bị chiếc siêu xe đâm trúng đêm đó là ai không? Chính là con bé em gái sinh đôi của cô đấy! Chính tôi đã bí mật cắt đứt dây phanh xe máy của nó và tạo hiện trường để dụ chiếc siêu xe của Cẩm Thần đâm vào! Còn Cẩm Thần ư? Sau khi tỉnh rượu, anh ấy đã hoàn toàn tin vào bản giám định giả mạo do bố tôi làm ra, tin rằng chính cô là kẻ trộm xe lái ẩu hại chết em gái mình rồi đổ vấy tội lỗi! Cả đời này anh ấy sẽ căm thù cô tột cùng! Cứ mục rữa trong bốn bức tường đá này đi con ngốc!'.\n\nTin tức ấy như sét đánh ngang tai, bóp nghẹt buồng phổi Thẩm Diên, khiến cô nôn ra một búng máu tươi ngay tại phòng thăm nuôi! Cái chết oan khiên của người em gái nhỏ vô tội cùng sự tráo trở tàn độc của Bạch gia đã biến năm năm ngục tù của Thẩm Diên thành một chuỗi ngày địa ngục trần gian. Nơi trại giam vùng núi tuyết buốt giá, mùa đông nhiệt độ âm năm độ C, cô phải dùng đôi bàn tay vốn chỉ quen chạm vào phím đàn piano để khiêng vác từng tảng đá hộc nặng hàng chục ký lô, ăn những bát cơm hẩm mốc meo lẫn cát sạn, chịu đựng những trận đòn ghen tuông đánh đập dã man từ những bạn tù bất hảo được Bạch gia ngầm chi tiền mua chuộc. Những đêm đông sốt cao run rẩy trong xà lim ẩm mốc, khi cơn co giật buốt tận tủy sống tưởng chừng cướp đi sinh mạng, Thẩm Diên đã tự cắn rách ngón tay mình, dùng máu viết lên tường từng nét chữ: 'Phải sống! Phải sống để đòi lại công lý cho em gái!'.\n\nVà hôm nay, cô đã đứng ở đây, đối diện trực tiếp với kẻ thủ ác và kẻ phụ tình! Thẩm Diên không hề né tránh ánh mắt khinh miệt của Phó Cẩm Thần, cô cười – một nụ cười thê lương nhưng ngập tràn khí phách kiên cường bất khuất: 'Phó Cẩm Thần, anh mở to mắt ra mà nhìn chiếc USB mạ vàng này đi! Đây là toàn bộ video trích xuất từ camera giám sát hành trình nguyên bản và biên bản xét nghiệm độc chất trong máu của anh đêm tai nạn năm năm trước! Bác quản gia già trung thành của gia đình anh trước khi nhắm mắt qua đời vì bạo bệnh đã không thể chịu nổi sự cắn rứt lương tâm nên đã bí mật trao nó cho luật sư của tôi! Kẻ cầm lái đêm hôm đó... nồng độ cồn vượt mức cho phép gấp năm lần... chính là anh đấy, Phó tổng tài cao quý! Còn người phụ nữ đoan trang đang đứng nép bên cạnh anh kia, chính là kẻ đã thuê côn đồ cắt phanh xe máy em gái tôi để giăng cái bẫy hoàn hảo này!'.\n\nLời tuyên bố đanh thép của Thẩm Diên như một quả bom nguyên tử phát nổ giữa khán phòng tiệc đính hôn! Tiếng xì xào bàn tán nổ ra dữ dội giữa hàng trăm quan khách, những chiếc điện thoại thông minh giơ lên quay chụp liên tục. Sắc mặt Bạch Uyển Đình trong tích tắc trắng bệch như tờ giấy quyến, ả giật bắn mình lùi lại hai bước, giọng nói run rẩy the thé hoảng loạn: 'Vu khống! Con điên này đang vu khống trắng trợn! Bảo vệ đâu! Giật lấy chiếc USB đó ngay! Đập nát nó đi cho tao! Đừng để nó ăn nói xằng bậy bôi nhọ danh dự Bạch gia!'.\n\nBốn tên vệ sĩ to lớn mặc đồ đen lập tức rút dùi cui lao tới định khống chế Thẩm Diên và cướp lấy chiếc USB bằng bạo lực. Nhưng Thẩm Diên đã nhanh như chớp lùi lại một bước, tay kia rút ra một chiếc bật lửa kim loại, ngón tay bấm 'tách' một tiếng dứt khoát! Ngọn lửa vàng rực bùng lên soi rõ khuôn mặt gầy guộc kiên cường không một chút sợ hãi của cô: 'Đừng bước lại gần! Toàn bộ tệp dữ liệu gốc trong chiếc USB này tôi đã cài đặt chế độ tự động đồng bộ hóa lên cổng thông tin của Viện Kiểm sát Nhân dân Tối cao và gửi tới tòa soạn của mười tờ báo lớn nhất cả nước! Nếu trong vòng hai tiếng nữa tôi không đăng nhập hủy lệnh khẩn cấp, đúng mười hai giờ đêm nay, toàn bộ sự thật đen tối về vụ tai nạn năm năm trước sẽ được công khai trước toàn thể nhân dân cả nước!'.\n\nPhó Cẩm Thần nhìn trừng trừng vào Thẩm Diên, lồng ngực anh phập phồng dữ dội. Khi ánh mắt anh lướt qua cổ tay trái gầy guộc của cô, đồng tử anh bỗng nhiên rung chuyển kịch liệt khi nhìn thấy một vết sẹo mổ dài hơn mười lăm phân đã lồi sần sùi – đó là vết sẹo sau lần cô tự rạch cổ tay phản đối sự bất công trong trại giam. Trong tâm trí hỗn loạn của vị tổng tài kiêu ngạo, một ký ức mơ hồ nhưng nhức nhối từ đêm tai nạn năm xưa bỗng hiện về: Mùi máu tanh nồng nặc trong khoang xe bẹp dúm, đôi bàn tay ấm áp run rẩy của một cô gái ôm lấy khuôn mặt anh, tiếng nấc nghẹn ngào thì thào bên tai: 'Cẩm Thần, anh nhất định phải sống tốt để kế thừa tập đoàn, em sẽ gánh hết tội lỗi thay anh...'.\n\nTrái tim Phó Cẩm Thần bỗng nhói buốt như bị hàng ngàn mũi kim châm, anh bước dồn dập về phía cô, giọng nói khàn đặc run rẩy: 'Thẩm Diên... cô vừa nói cái gì? Người lái xe đêm đó... thực sự là tôi sao?'. Thế nhưng Thẩm Diên chỉ lạnh lùng nhìn anh bằng đôi mắt trống rỗng không còn một tia cảm xúc, như nhìn một nắm tro tàn vô giá trị: 'Phó Cẩm Thần, tình yêu của Thẩm Diên này dành cho anh đã chết rục trong xà lim ẩm mốc từ năm năm trước rồi! Hôm nay tôi đến đây không phải để cầu xin tình thương hại hay mong anh quay lại, mà là để tống cổ những kẻ mang tội ác tày trời vào đúng vị trí của chúng! Danh dự của tôi, mạng sống của em gái tôi, các người phải trả lại không thiếu một ly!'. Dứt lời, Thẩm Diên kiêu hãnh quay lưng bước đi giữa những ánh nhìn bàng hoàng của toàn thể quan khách.\n\nPhó Cẩm Thần hốt hoảng lao theo định giữ lấy cánh tay Thẩm Diên, nhưng đúng khoảnh khắc ngón tay anh vừa chạm vào mép áo khoác cũ của cô, một tiếng sấm sét nổ vang làm mất toàn bộ ánh sáng trong khách sạn! Giữa bóng tối hỗn loạn và tiếng la hét thất thanh, một bóng đen bất ngờ vung chiếc gậy sắt giáng mạnh một đòn chí tử vào sau gáy Thẩm Diên, khiến cô ngã quỵ xuống vũng nước mưa buốt giá ngoài cửa sảnh, máu tươi loang lổ trên nền đá trắng tinh khôi!"
    part2_full = "Ngoài hiên sảnh tiệc khách sạn, cơn mưa đêm trút xuống xối xả làm loang đỏ vệt máu trên nền đá trắng, nơi Phó Cẩm Thần quỳ sụp xuống ôm chặt lấy cơ thể bất tỉnh của tôi. Anh điên cuồng lao ra ngoài cửa sảnh giữa cơn mưa buốt giá, tung một cú đá sấm sét đạp văng tên sát thủ bịt mặt đang cầm chiếc gậy sắt dính máu. Tên sát thủ hoảng sợ nhảy lên chiếc mô tô phân khối lớn nổ máy rồ ga phóng bạt mạng vào màn mưa đêm tẩu thoát. Phó Cẩm Thần quỳ sụp hai gối xuống vũng nước mưa lạnh ngắt ngập ngụa bùn đất, hai bàn tay run rẩy ôm lấy thân thể gầy guộc, nhẹ bẫng như một chiếc lá khô của Thẩm Diên vào lòng. Máu tươi đỏ thẫm từ sau gáy cô tuôn ra xối xả, nhuộm đỏ cả vạt áo sơ mi trắng đắt tiền của anh và hòa lẫn vào dòng nước mưa buốt giá. Khuôn mặt Thẩm Diên trắng bệch không còn một giọt máu, đôi mắt nhắm nghiền, hơi thở mong manh như sợi tơ sắp đứt giữa gió giông.\n\nLần đầu tiên trong cuộc đời ba mươi năm kiêu hãnh đứng trên đỉnh cao tiền tài và danh vọng, Phó Cẩm Thần cảm nhận được nỗi sợ hãi tột cùng bóp nghẹt lồng ngực mình đến mức không thở nổi! Cảm giác như chính linh hồn anh đang bị xé toạc ra từng mảnh vụn. Anh bế xốc cô lên chạy thục mạng ra xe, hét lớn vào mặt viên tài xế riêng đang run rẩy: 'Lái xe đến Bệnh viện Trung ương ngay lập tức! Vượt toàn bộ đèn đỏ! Gọi ngay cho Giám đốc bệnh viện, bảo ông ta huy động toàn bộ chuyên gia phẫu thuật thần kinh giỏi nhất! Nếu đêm nay Thẩm Diên có mệnh hệ nào, tôi thề sẽ san phẳng toàn bộ cái bệnh viện đó!'.\n\nSuốt bảy tiếng đồng hồ căng thẳng tột độ bên ngoài phòng phẫu thuật cấp cứu đặc biệt, ánh đèn đỏ phẫu thuật như ngọn lửa thiêu đốt từng khúc ruột của Phó Cẩm Thần. Anh ngồi bất động trên hàng ghế sắt lạnh lẽo ngoài hành lang, quần áo vẫn ướt sũng nước mưa và loang lổ những vệt máu tươi đã khô thẫm lại. Đôi bàn tay anh run rẩy không ngừng, từng khớp xương nhức buốt vì lo sợ. Đúng lúc ấy, người trợ lý thân cận của anh mang đến một tập hồ sơ mật dày cộp được niêm phong cẩn thận từ cơ quan giám định: 'Phó tổng... chúng tôi đã giải mã toàn bộ dữ liệu trong chiếc USB và cử người tiếp cận hồ sơ lưu trữ của Viện Kiểm sát... Những gì cô Thẩm nói tại sảnh tiệc... hoàn toàn là sự thật một trăm phần trăm! Đêm tai nạn năm năm trước, chính Bạch Uyển Đình đã bỏ thuốc kích thích vào ly rượu vang của ngài tại nhà hàng, sau đó cho người dụ xe máy của em gái cô Thẩm ra đường cao tốc... Người lái xe gây tai nạn thực sự là ngài. Cô Thẩm vì muốn bảo vệ ngài và tập đoàn nên đã cắn răng ký vào biên bản nhận tội thay... Và đây... đây là hồ sơ bệnh án tối mật của cô Thẩm trong thời gian thụ án tại Trại giam số 4...'.\n\nPhó Cẩm Thần run rẩy cầm tập tài liệu y tế dày cộm, lật giở từng trang giấy đã ố vàng. Và khi những dòng chữ y khoa hiện ra trước mắt, trái tim anh như bị một bàn tay vô hình bóp nát vụn ra thành trăm mảnh: Năm thứ hai trong tù, Thẩm Diên bị viêm phổi thùy nặng do lao động trong hầm đá rét buốt âm mười độ, suýt không qua khỏi vì thiếu thuốc men; Năm thứ ba... cô đã tự nguyện ký vào bản cam kết hiến tặng tủy ẩn danh cho một bệnh nhân ung thư máu giai đoạn cuối – mà mã số bệnh nhân nhận tủy in đậm trên hồ sơ... chính là mã số bệnh án của Phó Cẩm Thần trong đợt anh lâm bạo bệnh thập tử nhất sinh ba năm trước!\n\nAnh vẫn nhớ như in, ba năm trước anh bất ngờ phát hiện mắc chứng suy tủy và ung thư máu cấp tính, các chuyên gia huyết học hàng đầu thế giới đều lắc đầu bất lực vì không tìm được mẫu tủy tương thích sinh học. Đúng lúc gia đình anh chuẩn bị lo hậu sự thì bất ngờ có một mẫu tủy tương thích tuyệt đối một trăm phần trăm được gửi tới từ một nguồn ẩn danh, cứu sống mạng sống của anh trong gang tấc! Sau khi bình phục, Bạch Uyển Đình đã khóc lóc kể rằng chính gia đình cô ta đã bỏ ra hàng triệu đô la Mỹ để tìm kiếm nguồn tủy cứu anh ở nước ngoài, khiến anh vô cùng cảm kích và đồng ý hứa hôn với ả... Hóa ra tất cả chỉ là một màn kịch lừa đảo bẩn thỉu và trơ trẽn!\n\nNgười thực sự đã cứu mạng anh, người đã cho anh sự sống thứ hai này... lại chính là người con gái mà anh từng nhẫn tâm đẩy vào ngục tối, người mà anh đã buông lời sỉ nhục, khinh miệt không thương tiếc suốt năm năm trời! Để có đủ lượng tủy cứu sống anh, Thẩm Diên khi ấy chỉ nặng chưa đầy bốn mươi ký lô, thể trạng suy kiệt trầm trọng, đã phải chịu đựng những mũi kim chọc tủy khổng lồ đâm sâu vào xương chậu đau đớn thấu tận tim gan mà không thể dùng thuốc giảm đau liều cao vì sợ ảnh hưởng chất lượng tế bào gốc! Sau ca lấy tủy nghiệt ngã ấy, cô đã ngất lịm trên sàn trại giam suốt ba ngày ba đêm, sốt li bì suýt mất mạng, nhưng đôi môi nứt nẻ vẫn thì thào cầu nguyện cho anh được bình an!\n\nMột tiếng thét nghẹn ngào xé ruột xé gan từ sâu thẳm lồng ngực Phó Cẩm Thần bật ra, anh đấm mạnh nắm tay vào bức tường bê tông cốt thép đến mức da thịt rách toạc, máu tươi chảy ròng ròng trên nền gạch men trắng! Nỗi đau đớn, sự ân hận tột cùng và nỗi căm ghét chính bản thân mình như những đợt sóng thần hung hãn nhấn chìm toàn bộ tâm trí anh. Anh là một kẻ mù quáng! Một kẻ khốn nạn vô tâm đã tự tay chà đạp lên người phụ nữ yêu anh hơn cả sinh mạng mình! Đúng lúc đó, cánh cửa phòng phẫu thuật bật mở, vị giáo sư đầu ngành bước ra với nét mặt mệt mỏi nhưng nhẹ nhõm phần nào: 'Bệnh nhân bị chấn thương sọ não kín và rách da đầu sâu, nhưng may mắn hộp sọ không bị vỡ. Chúng tôi đã phẫu thuật cầm máu thành công và khâu lại vết thương. Tuy nhiên thể trạng của cô ấy quá mức suy kiệt, huyết áp rất thấp. Đặc biệt, các dây thần kinh vận động ở ngón tay của cô ấy đã bị xơ hóa nghiêm trọng từ những năm tháng lao động nặng trước đây, có lẽ vĩnh viễn không thể chơi đàn piano chuyên nghiệp được nữa... Bệnh nhân đã tỉnh lại, nhưng cô ấy yêu cầu tuyệt đối không muốn nhìn thấy ngài'.\n\nMặc kệ lời can ngăn tha thiết của các y bác sĩ, Phó Cẩm Thần bước vào phòng chăm sóc đặc biệt bằng những bước chân nặng trĩu như đeo chì. Nhìn thấy Thẩm Diên nằm bất động trên giường bệnh trắng toát, đầu quấn băng trắng dày cộp, khuôn mặt nhỏ nhắn gầy gò nhìn lên trần nhà với đôi mắt trống rỗng không chút hồn vía, người đàn ông quyền lực nhất thành phố bỗng quỳ sụp hai gối xuống bên mép giường bệnh! Anh run rẩy đưa bàn tay đẫm máu của mình áp vào bàn tay lạnh ngắt của cô, những giọt nước mắt sám hối nóng hổi của một người đàn ông kiêu ngạo tuôn rơi lã chã xuống mu bàn tay chằng chịt sẹo của cô: 'Thẩm Diên... anh sai rồi... anh là một thằng khốn nạn mù quáng! Anh đã đọc hết hồ sơ bệnh án rồi... Anh biết em là người hiến tủy cứu mạng anh... Anh cầu xin em, em hãy cầm dao đâm chết anh đi, em hãy đánh đập trừng phạt anh thế nào cũng được, nhưng xin em đừng nhìn anh bằng ánh mắt xa lạ, lạnh lùng như thế này có được không? Anh sẽ dùng cả cuộc đời còn lại, dùng toàn bộ gia sản của Phó Thị để bù đắp và chuộc tội với em!'.\n\nThế nhưng đáp lại sự quỳ lạy đau đớn của anh, Thẩm Diên chỉ chậm rãi rút bàn tay mình ra khỏi sự kìm kẹp của anh, khuôn mặt không một chút gợn sóng, giọng nói khẽ khàng nhưng sắc lạnh buốt giá như băng tuyết ngàn năm: 'Phó Cẩm Thần, năm năm trước khi tôi quỳ trước cổng biệt thự Phó gia dưới trời mưa bão cầu xin anh tin tôi một lần, anh đã nói gì? Anh nói tôi là thứ đàn bà dơ bẩn, mưu mô, hám tiền, không xứng đáng xuất hiện trước mặt anh. Bây giờ anh biết sự thật rồi thì có ích gì nữa sao? Em gái tôi có sống lại được không? Bàn tay chơi đàn của tôi có hồi phục lại được không? Năm năm thanh xuân tủi nhục trong ngục tối của tôi có quay trở lại được không? Phó tổng tài, sự ân hận muộn màng của anh... đối với tôi chỉ là một trò hề ghê tởm mà thôi! Giữa chúng ta chỉ còn lại bản cáo trạng trước tòa án pháp luật!'.\n\nĐúng lúc không khí đang đóng băng ngột ngạt, cánh cửa phòng bệnh bất ngờ bị đạp tung ra một tiếng 'RẦM'! Bạch Uyển Đình xuất hiện trong bộ dạng điên loạn tột cùng, đầu tóc rũ rượi, trên tay lăm lăm một lọ thủy tinh lớn chứa đầy dung dịch axit sunfuric đậm đặc bốc khói nghi ngút, đôi mắt ả đỏ quạch hằn lên những tia máu man rợ: 'Thẩm Diên! Mày đã phá hủy tiệc đính hôn của tao, hủy hoại danh tiếng lẫy lừng của Bạch gia! Cảnh sát đang phong tỏa tài sản nhà tao! Đêm nay tao sẽ tạt axit hủy hoại hoàn toàn khuôn mặt này để xem mày còn dám quyến rũ Cẩm Thần nữa không! Cả hai chúng mày đều phải chết cùng tao!'. Tên vệ sĩ đi theo sau ả lập tức khóa trái then cửa phòng bệnh từ bên trong!\n\nBạch Uyển Đình điên cuồng vung tay hắt mạnh toàn bộ lọ axit đậm đặc bốc khói nghi ngút thẳng vào mặt Thẩm Diên đang nằm trên giường bệnh! Trong tích tắc ngàn cân treo sợi tóc giữa sự sống và cái chết, một bóng đen cao lớn bất thần lao tới chắn ngang trước mặt cô! Một tiếng xèo xèo rợn người kèm theo mùi da thịt cháy khét lẹt bốc lên nồng nặc, và tiếng gầm đau đớn xé ruột xé gan của Phó Cẩm Thần vang lên chấn động cả tầng lầu bệnh viện!"
    part3_full = "Mùi thuốc sát trùng nồng nặc bao trùm hành lang tầng bảy bệnh viện trung ương, khi vết bỏng hóa chất trên bờ vai Phó Cẩm Thần thấm đỏ cả lớp băng gạc trắng. Cơn đau đớn tột cùng như bị hàng ngàn ngọn lửa địa ngục thiêu đốt sống khiến toàn thân anh co giật dữ dội, mồ hôi lạnh toát ra ướt đẫm vầng trán tái mét, từng mạch máu nơi thái dương giật giật điên cuồng. Thế nhưng dù phải chịu đựng nỗi đau đớn thể xác vượt quá giới hạn chịu đựng của một con người, hai cánh tay rắn rỏi của Phó Cẩm Thần vẫn ghì chặt lấy thân thể Thẩm Diên trong lòng ngực mình, dùng toàn bộ tấm lưng rộng lớn của mình làm lá chắn che chở vững chắc, không để một giọt axit chết chóc nào bắn trúng vào da thịt cô!\n\nGiữa khoảnh khắc sinh tử ngàn cân treo sợi tóc ấy, ánh mắt Phó Cẩm Thần nhìn Thẩm Diên lại ngập tràn sự dịu dàng, che chở và thanh thản kỳ lạ. Anh khẽ run rẩy đưa bàn tay còn lành lặn vuốt nhẹ mái tóc cô, giọng nói thì thào đứt quãng trong hơi thở gấp gáp: 'Thẩm Diên... em không sao là tốt rồi... Năm năm trước anh nợ em một mạng sống... Lần này... anh cuối cùng cũng đã bảo vệ được em rồi...'. Nói dứt câu nói ấy, toàn bộ sức lực của người đàn ông kiêu ngạo cạn kiệt, Phó Cẩm Thần ngã gục xuống sàn nhà bất tỉnh nhân sự vì cơn sốc đau đớn tột cùng!\n\nBạch Uyển Đình kinh hoàng nhìn lọ thủy tinh rỗng tuếch trên tay mình, chưa kịp quay đầu bỏ chạy thì cánh cửa phòng bệnh đã bị lực lượng Cảnh sát Cơ động cùng Viện Kiểm sát đạp tung ập vào! Bốn họng súng ngắn chĩa thẳng vào ngực ả, chiếc còng số tám sáng loáng bập vào hai cổ tay ả kêu 'tách' một tiếng đanh thép! Kiểm sát viên cao cấp nghiêm giọng tuyên bố lệnh bắt khẩn cấp: 'Bạch Uyển Đình! Cô bị bắt vì tội chủ mưu giết người có tổ chức, tạt axit trả thù và làm sai lệch hồ sơ vụ án tai nạn giao thông nghiêm trọng năm năm trước! Toàn bộ camera an ninh bệnh viện và lời khai của tên vệ sĩ đã ghi lại đầy đủ chứng cứ phạm tội của cô! Toàn bộ tài sản của gia tộc họ Bạch đã bị phong tỏa phục vụ công tác điều tra tham nhũng và hối lộ tư pháp!'. Ả thiên kim tiểu thư lẫy lừng ngày nào giờ đây gào khóc thảm thiết, quằn quại bị áp giải đi trong sự khinh bỉ tột cùng của mọi người xung quanh, đối mặt với mức án từ hai mươi năm tù đến chung thân cho những tội ác tày trời của mình.\n\nCa phẫu thuật cấp cứu hồi sức, cắt lọc mô hoại tử và ghép da trên diện rộng cho Phó Cẩm Thần kéo dài suốt mười hai tiếng đồng hồ căng thẳng. Đứng bên ngoài cửa kính phòng hồi sức tích cực, Thẩm Diên nhìn người đàn ông đang nằm sấp bất động với toàn bộ tấm lưng được băng bó kín mít bởi lớp gạc vô trùng, trái tim cô vốn đã đóng băng suốt năm năm qua bỗng run lên từng nhịp đập đau đớn khôn nguôi. Cô căm ghét sự mù quáng, vô tình của anh trong quá khứ, nhưng hành động xả thân lấy chính thân mình làm bia đỡ axit vừa rồi của anh đã chứng minh rằng, anh thực sự sẵn sàng dùng mạng sống của mình để đổi lấy sự an toàn cho cô. Trong suốt sáu tháng anh nằm viện điều trị phục hồi chức năng, Thẩm Diên đã lặng lẽ đến bên giường bệnh chăm sóc anh mỗi đêm, tự tay thay băng và bôi thuốc cho từng vết sẹo bỏng chằng chịt, sần sùi trên lưng anh. Phó Cẩm Thần kiên quyết từ chối dùng thuốc giảm đau liều cao mỗi khi thay băng, bởi anh nói rằng nỗi đau thể xác rát bỏng này chẳng thấm tháp vào đâu so với nỗi đau tinh thần và sự cô độc mà Thẩm Diên đã phải gánh chịu suốt năm năm trong ngục tối giá lạnh.\n\nKhi Phó Cẩm Thần bình phục và có thể ngồi dậy trên xe lăn, anh run rẩy móc từ dưới gối ra một tập hồ sơ chuyển nhượng tài sản pháp lý đã được anh ký tên và đóng dấu sẵn từ trước: 'Thẩm Diên... toàn bộ tám mươi phần trăm cổ phần của tập đoàn Phó Thị, căn biệt thự bên bờ biển và ba tòa nhà thương mại tại trung tâm thủ đô... anh đã làm thủ tục chuyển toàn bộ quyền sở hữu sang tên em... Đó là tất cả những gì anh có thể làm để chuộc lại một phần tội lỗi và thanh xuân của em... Anh biết em sẽ không bao giờ tha thứ cho những sai lầm trong quá khứ... Sau khi em tiếp nhận toàn bộ tài sản, anh sẽ rời khỏi thành phố này vĩnh viễn, sang vùng núi xa xôi sống nốt phần đời còn lại, không bao giờ xuất hiện làm phiền cuộc sống tự do của em nữa...'.\n\nThẩm Diên cầm tập tài liệu pháp lý nặng trịch trên tay, nhìn những giọt nước mắt đàn ông lặng lẽ lăn dài trên gò má hốc hác, tiều tụy của anh. Trước sự ngỡ ngàng tột độ của Phó Cẩm Thần, cô từ từ dùng hai tay xé toạc bản hợp đồng chuyển nhượng nghìn tỷ ra làm đôi, rồi làm bốn, rải những mảnh giấy vụn bay lơ lửng trong không trung: 'Phó Cẩm Thần, tôi ngồi tù năm năm là vì tôi từng yêu anh thật lòng, chứ không phải vì tám mươi phần trăm cổ phần của Phó Thị! Và nhát axit vừa rồi anh gánh thay cho tôi, coi như đã trả xong món nợ máu năm xưa của chúng ta. Giữa chúng ta... từ nay ân oán xóa sạch, không ai nợ ai bất cứ điều gì nữa!'. Phó Cẩm Thần chết lặng, ánh mắt ngập tràn sự tuyệt vọng tột cùng: 'Vậy... chúng ta thực sự kết thúc rồi sao?'.\n\nThẩm Diên quay lưng bước chầm chậm về phía cửa phòng bệnh. Thế nhưng ngay khi tay cô chạm vào then cài cửa, cô bỗng dừng bước, khẽ ngoảnh đầu lại nhìn người đàn ông đang gục đầu đau đớn trên giường bệnh, giọng nói trầm ấm hơn đôi phần: 'Phó Cẩm Thần, vết thương bỏng trên lưng anh cần thêm thời gian để liền sẹo. Và vết thương rỉ máu trong lòng tôi... có lẽ cần cả cuộc đời này để chữa lành. Tôi đã dùng số tiền bồi thường oan sai để mở một trung tâm dạy đàn piano cho trẻ em nghèo và văn phòng hỗ trợ pháp lý miễn phí cho những phụ nữ từng chịu oan ức... Liệu anh có đủ kiên nhẫn để cùng tôi làm lại từ đầu, bắt đầu lại từ những việc nhỏ bé nhất của một con người bình thường không?'.\n\nLời nói dịu dàng ấy như một luồng ánh sáng thần kỳ thắp sáng lại linh hồn đang lụi tàn của Phó Cẩm Thần! Anh ngẩng phắt đầu lên, trong đôi mắt đẫm lệ bỗng bùng cháy lên ngọn lửa hy vọng rực rỡ nhất trần đời: 'Anh hứa! Dù phải dùng mười năm, hai mươi năm hay cả kiếp này... anh nhất định sẽ dùng cả trái tim để đồng hành, chăm sóc và bảo vệ em!'. Nắng ấm ban mai chiếu qua khung cửa sổ bệnh viện, sưởi ấm căn phòng sau những ngày mưa bão tăm tối kéo dài. Bông hoa sơn tra từng tàn lụi trong hận thù, nước mắt và máu tươi, giờ đây đang chuẩn bị đâm chồi nảy lộc trở lại dưới ánh bình minh của sự thứ tha và chân tình son sắt. Tình yêu đích thực không phải là sự chiếm đoạt hay bù đắp bằng tiền bạc vật chất, mà là sự dũng cảm đối diện với sai lầm, cùng nhau gánh vác tổn thương và hướng về một tương lai tươi sáng, trọn vẹn nghĩa tình. Dù con đường phía trước còn muôn vàn gian nan trắc trở, nhưng khi hai trái tim đã thấu hiểu nỗi đau của nhau và cùng hướng về ánh sáng, vết thương nào rồi cũng sẽ lành lặn theo năm tháng, để đóa hoa tình yêu được hồi sinh trọn vẹn và tỏa hương thơm ngát giữa cuộc đời.\n\nTheo bạn, sau những tổn thương xé lòng trong quá khứ, liệu sự hối hận chân thành và màn hy sinh tính mạng của Phó Cẩm Thần có xứng đáng để Thẩm Diên mở lòng tha thứ? Hãy để lại quan điểm của bạn dưới phần bình luận nhé!"
